"""Trace only an owned child tree; no host ptrace/sysctl changes."""
import ctypes
import errno
import json
import os
from pathlib import Path
import platform
import select
import signal
import subprocess
import sys
import time

libc = ctypes.CDLL(None, use_errno=True)
libc.ptrace.restype = ctypes.c_long
PTRACE_TRACEME=0;PTRACE_SYSCALL=24;PTRACE_SETOPTIONS=0x4200
PTRACE_GETEVENTMSG=0x4201;PTRACE_GETREGS=12
PTRACE_PEEKDATA=2
OPTIONS=1|2|4|8|16|32|64|0x100000
WALL=0x40000000
SYSCALL_STOP=signal.SIGTRAP|0x80


class Registers(ctypes.Structure):
    _fields_ = [(name, ctypes.c_ulonglong) for name in
                ('r15','r14','r13','r12','rbp','rbx','r11','r10','r9','r8','rax','rcx',
                 'rdx','rsi','rdi','orig_rax','rip','cs','eflags','rsp','ss',
                 'fs_base','gs_base','ds','es','fs','gs')]


def ptrace(request, pid, address=0, data=0):
    ctypes.set_errno(0)
    result = libc.ptrace(ctypes.c_ulong(request), ctypes.c_ulong(pid),
                         ctypes.c_void_p(address),
                         ctypes.cast(data, ctypes.c_void_p) if not isinstance(data,int) else ctypes.c_void_p(data))
    if result == -1 and ctypes.get_errno():
        raise OSError(ctypes.get_errno(), os.strerror(ctypes.get_errno()))
    return result


def process(pid):
    try:
        text=Path('/proc/'+str(pid)+'/stat').read_text()
        rest=text[text.rindex(')')+2:].split()
        return {'state':rest[0],'ppid':int(rest[1]),'pgid':int(rest[2]),'sid':int(rest[3]),
                'starttime':int(rest[19]),'wchan':Path('/proc/'+str(pid)+'/wchan').read_text().strip()}
    except (FileNotFoundError,ProcessLookupError):
        return None


def read_integer(pid,address):
    aligned=address&~7
    word=ptrace(PTRACE_PEEKDATA,pid,aligned,0)
    return ctypes.c_int((word >> (8*(address-aligned)))&0xffffffff).value


def trace(binary,args,seconds=8,memory_address=None):
    if sys.platform!='linux' or platform.machine() not in ('x86_64','amd64'):
        raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: reviewed tracer requires Linux x86_64')
    assert os.getuid()!=0,'nonroot own-child tracing required'
    output_read,output_write=os.pipe();error_read,error_write=os.pipe()
    pid=os.fork()
    if pid==0:
        os.close(output_read);os.close(error_read)
        os.dup2(output_write,1);os.dup2(error_write,2);os.close(output_write);os.close(error_write)
        os.setsid()
        ptrace(PTRACE_TRACEME,0)
        os.kill(os.getpid(),signal.SIGSTOP)
        os.execve(str(binary),[str(binary),*args],dict(os.environ))
    os.close(output_write);os.close(error_write)
    os.set_blocking(output_read,False);os.set_blocking(error_read,False)
    owned={pid};known={pid};events=[];syscalls=[];syscall_exits=[];exits={};vfork_parent={};waiting=[]
    child_parents={};memory_before={};memory_samples=[];held_waiters={};held_exits={};sampled=set()
    chunks={output_read:[],error_read:[]};started=time.monotonic()
    def drain():
        for descriptor in (output_read,error_read):
            while select.select([descriptor],[],[],0)[0]:
                try:block=os.read(descriptor,8192)
                except BlockingIOError:break
                if not block:break
                chunks[descriptor].append(block)
                assert sum(map(len,chunks[descriptor]))<100000,'bounded native output exceeded'
    try:
        while owned:
            if time.monotonic()-started>seconds:raise AssertionError('own-child native trace timeout')
            drain()
            waited,status=os.waitpid(-1,os.WNOHANG|WALL)
            if waited==0:
                time.sleep(.001);continue
            assert waited in known,'unexpected child in private trace'
            if os.WIFEXITED(status):
                exits[waited]={'exit_code':os.WEXITSTATUS(status)};owned.discard(waited);continue
            if os.WIFSIGNALED(status):
                exits[waited]={'signal':os.WTERMSIG(status)};owned.discard(waited);continue
            if not os.WIFSTOPPED(status):continue
            stop=os.WSTOPSIG(status);event=status>>16
            resumed=set()
            if stop==signal.SIGSTOP:
                ptrace(PTRACE_SETOPTIONS,waited,0,OPTIONS)
                if waited in vfork_parent:
                    parent=vfork_parent[waited]
                    time.sleep(.015)
                    waiting.append({'parent':parent,'child':waited,'parent_before_child_exec':process(parent),
                                    'child_before_exec_exe':os.readlink('/proc/'+str(waited)+'/exe')})
            if event:
                item={'tid':waited,'event':event}
                if event in (1,2,3,5):
                    message=ctypes.c_ulonglong()
                    ptrace(PTRACE_GETEVENTMSG,waited,0,ctypes.byref(message));item['related_tid']=message.value
                    if event in (1,2,3):
                        owned.add(message.value);known.add(message.value)
                        child_parents[message.value]=waited
                        if memory_address is not None and waited==pid:
                            memory_before[message.value]=read_integer(waited,memory_address)
                    if event==2:vfork_parent[message.value]=waited
                if event==4:item['exe']=os.readlink('/proc/'+str(waited)+'/exe')
                events.append(item)
                if event==6 and memory_address is not None and child_parents.get(waited)==pid and waited not in sampled:
                    held_exits[waited]=pid
            if stop==SYSCALL_STOP:
                registers=Registers();ptrace(PTRACE_GETREGS,waited,0,ctypes.byref(registers))
                # On x86_64 PTRACE_SYSCALL entry stops expose -ENOSYS in RAX.
                if registers.rax==(2**64-errno.ENOSYS):
                    syscalls.append({'tid':waited,'number':registers.orig_rax,
                                     'args':[registers.rdi,registers.rsi,registers.rdx,registers.r10,registers.r8,registers.r9]})
                    if memory_address is not None and waited==pid and registers.orig_rax==61:
                        children=[child for child,parent in child_parents.items() if parent==pid and child not in sampled]
                        if len(children)==1:
                            held_waiters[waited]=children[0]
                elif registers.orig_rax==61:
                    returned=registers.rax if registers.rax<2**63 else registers.rax-2**64
                    syscall_exits.append({'tid':waited,'number':61,'returned':returned})
            for parent,child in list(held_waiters.items()):
                if child in held_exits:
                    memory_samples.append({'parent':parent,'child':child,'address':memory_address,
                                           'parent_before_creation':memory_before[child],
                                           'parent_after_child_before_reap':read_integer(parent,memory_address),
                                           'child_before_exit':read_integer(child,memory_address)})
                    sampled.add(child);del held_waiters[parent];del held_exits[child]
                    ptrace(PTRACE_SYSCALL,child,0,0);ptrace(PTRACE_SYSCALL,parent,0,0)
                    resumed.update((parent,child))
            delivered=0 if stop in (signal.SIGTRAP,SYSCALL_STOP,signal.SIGSTOP) else stop
            if waited not in resumed and waited not in held_waiters and waited not in held_exits:
                try:ptrace(PTRACE_SYSCALL,waited,0,delivered)
                except ProcessLookupError:pass
        drain()
        return {'root_pid':pid,'events':events,'syscalls':syscalls,'syscall_exits':syscall_exits,
                'memory_samples':memory_samples,'exits':exits,
                'vfork_wait_observations':waiting,
                'stdout':b''.join(chunks[output_read]).decode('utf-8'),
                'stderr':b''.join(chunks[error_read]).decode('utf-8'),
                'host_uid':os.getuid(),'seconds':round(time.monotonic()-started,3)}
    finally:
        for child in owned:
            try:os.kill(child,signal.SIGKILL)
            except ProcessLookupError:pass
        until=time.monotonic()+2
        while owned and time.monotonic()<until:
            try:
                child,status=os.waitpid(-1,os.WNOHANG|WALL)
                if child:
                    if os.WIFSTOPPED(status):
                        try:ptrace(PTRACE_SYSCALL,child,0,signal.SIGKILL)
                        except ProcessLookupError:pass
                    else:owned.discard(child)
                else:time.sleep(.005)
            except ChildProcessError:break
        os.close(output_read);os.close(error_read)


TARGET=r'''#include <stdio.h>
#include <string.h>
#include <unistd.h>
int main(int argc,char **argv){
 if(argc!=2||(strcmp(argv[1],"exec")&&strcmp(argv[1],"vfork")))return 2;
 printf("{\"mode\":\"target\",\"origin\":\"%s\",\"pid\":%ld,\"ppid\":%ld}\n",argv[1],(long)getpid(),(long)getppid());
 return 29;
}
'''


def compile_sources(directory,source):
    directory=Path(directory)
    target_source=directory/'trusted_exec_target.c';target_source.write_text(TARGET,encoding='utf-8')
    demo=directory/'demo';target=directory/'exec-target'
    for input_path,output_path in [(source,demo),(target_source,target)]:
        result=subprocess.run(['gcc','-std=gnu11','-O2','-Wall','-Wextra','-Werror','-fno-pie','-no-pie',
                               str(input_path),'-o',str(output_path)],capture_output=True,timeout=15)
        assert result.returncode==0,('native GCC compilation failed',result.stderr.decode(errors='replace'))
    return demo,target


def shared_value_address(binary):
    result=subprocess.run(['readelf','-sW',str(binary)],capture_output=True,text=True,timeout=5)
    assert result.returncode==0,result.stderr
    matches=[line.split()for line in result.stdout.splitlines()if line.split()and line.split()[-1]=='opsforge_shared_value']
    assert len(matches)==1 and matches[0][2]=='4' and matches[0][3]=='OBJECT' and matches[0][4]=='GLOBAL','required atomic observation symbol missing'
    return int(matches[0][1],16)
